//! Achievements + the persistent stats layer behind them.
//!
//! Pure data and rules, no raylib: the game builds a `Snapshot` of whatever
//! the rules need, `Tracker.evaluate` returns what just unlocked, and the
//! backends (in-game toast, Steam via steam.zig, the save file) react.
//! Names and descriptions live here in both languages: they feed the in-game
//! toast/stats screen and the Steamworks entry sheet (docs/achievements.md,
//! generated by `zig build achievements-sheet`).

const std = @import("std");
const locale = @import("localization.zig");

/// Declaration order is the Steamworks display order: cheap early ones
/// first (they show on the store page), hidden easter eggs last.
pub const Id = enum(u8) {
    first_drop,
    super_bloom,
    full_crew,
    local_business,
    hive_mind,
    wholesale,
    long_live_the_queen,
    liquid_gold,
    field_of_giants,
    botanical_trifecta,
    circle_of_life,
    land_baron,
    well_read,
    royal_treatment,
    dynasty,
    perennial,
    bee_llionaire,
    swarm,
    // hidden
    night_shift,
    dont_poke_the_hive,
    sticky_situation,
};

pub const COUNT = @typeInfo(Id).@"enum".fields.len;

/// Lifetime counters mirrored as Steam stats. They live in the save file,
/// survive prestige *and* New Game (like Steam's own account-level stats).
pub const Stat = enum(u8) {
    lifetime_honey,
    prestige_count,
    super_flowers_merged,
    rotten_cleared,
    max_bees_alive,

    pub const COUNT = @typeInfo(Stat).@"enum".fields.len;

    pub const Kind = enum { int, float };

    /// Steamworks API name of the stat.
    pub fn api(self: Stat) [:0]const u8 {
        return @tagName(self);
    }

    pub fn kind(self: Stat) Kind {
        return switch (self) {
            .lifetime_honey => .float,
            else => .int,
        };
    }

    pub fn fromApi(api_name: []const u8) ?Stat {
        inline for (@typeInfo(Stat).@"enum".fields) |f| {
            if (std.mem.eql(u8, api_name, f.name)) return @enumFromInt(f.value);
        }
        return null;
    }
};

pub const Stats = struct {
    /// Honey earned by the colony, ever. f64: late-game runs sit in the
    /// trillions, past f32's exact-integer range.
    lifetimeHoney: f64 = 0,
    prestigeCount: u32 = 0,
    superFlowersMerged: u32 = 0,
    rottenCleared: u32 = 0,
    /// High-water mark of live bees.
    maxBeesAlive: u32 = 0,

    pub fn get(self: *const Stats, stat: Stat) f64 {
        return switch (stat) {
            .lifetime_honey => self.lifetimeHoney,
            .prestige_count => @floatFromInt(self.prestigeCount),
            .super_flowers_merged => @floatFromInt(self.superFlowersMerged),
            .rotten_cleared => @floatFromInt(self.rottenCleared),
            .max_bees_alive => @floatFromInt(self.maxBeesAlive),
        };
    }

    /// Set from a parsed save value; negative / non-finite input clamps to 0.
    pub fn set(self: *Stats, stat: Stat, value: f64) void {
        const v = if (std.math.isFinite(value)) @max(0, value) else 0;
        const asInt: u32 = @intFromFloat(@min(v, @as(f64, @floatFromInt(std.math.maxInt(u32)))));
        switch (stat) {
            .lifetime_honey => self.lifetimeHoney = v,
            .prestige_count => self.prestigeCount = asInt,
            .super_flowers_merged => self.superFlowersMerged = asInt,
            .rotten_cleared => self.rottenCleared = asInt,
            .max_bees_alive => self.maxBeesAlive = asInt,
        }
    }
};

pub const Progress = struct {
    stat: Stat,
    target: f64,
};

pub const Def = struct {
    id: Id,
    /// Steamworks API name.
    api: [:0]const u8,
    name_en: [:0]const u8,
    name_pt: [:0]const u8,
    desc_en: [:0]const u8,
    desc_pt: [:0]const u8,
    /// Hidden in Steamworks: description concealed until unlocked.
    hidden: bool = false,
    /// Milestone achievements get a Steam progress bar driven by this stat.
    progress: ?Progress = null,
};

