comptime {
    for (DEFS, 0..) |d, i| {
        if (@intFromEnum(d.id) != i) @compileError("DEFS must be listed in Id order: " ++ d.api);
    }
}

pub fn def(id: Id) *const Def {
    return &DEFS[@intFromEnum(id)];
}

pub fn findByApi(api: []const u8) ?Id {
    for (&DEFS) |*d| {
        if (std.mem.eql(u8, d.api, api)) return d.id;
    }
    return null;
}

pub fn name(id: Id) [:0]const u8 {
    const d = def(id);
    return locale.tr(d.name_en, d.name_pt);
}

pub fn description(id: Id) [:0]const u8 {
    const d = def(id);
    return locale.tr(d.desc_en, d.desc_pt);
}

/// Everything the rules look at, sampled by the game once per tick.
pub const Snapshot = struct {
    stats: Stats = .{},
    beesAlive: u32 = 0,
    /// Indexed by components.BeeType: worker, swift, efficient, gardener.
    beeTypeCounts: [4]u32 = .{ 0, 0, 0, 0 },
    /// Live (non-rotten) SUPER flowers, and which types are represented
    /// (indexed by components.FlowerType: rose, tulip, dandelion).
    superFlowersAlive: u32 = 0,
    superTypesAlive: [3]bool = .{ false, false, false },
    /// Unspent Royal Jelly.
    availableJelly: u32 = 0,
    /// Most bees bought in one click since the last evaluation.
    largestPurchase: u32 = 0,
    allOneShotNodesOwned: bool = false,
    gridRingLevel: u16 = 0,
    nightShiftLevel: u16 = 0,
    hiveClickStreak: u32 = 0,
    fullStorageSeconds: f32 = 0,
};

pub fn isSatisfied(id: Id, s: *const Snapshot) bool {
    return switch (id) {
        .first_drop => s.stats.lifetimeHoney >= HONEY_FIRST_DROP,
        .local_business => s.stats.lifetimeHoney >= HONEY_LOCAL_BUSINESS,
        .liquid_gold => s.stats.lifetimeHoney >= HONEY_LIQUID_GOLD,
        .bee_llionaire => s.stats.lifetimeHoney >= HONEY_BEE_LLIONAIRE,
        .super_bloom => s.stats.superFlowersMerged >= 1,
        .field_of_giants => s.superFlowersAlive >= SUPER_FIELD_OF_GIANTS,
        .botanical_trifecta => s.superTypesAlive[0] and s.superTypesAlive[1] and s.superTypesAlive[2],
        .long_live_the_queen => s.stats.prestigeCount >= 1,
        .dynasty => s.stats.prestigeCount >= PRESTIGE_DYNASTY,
        .perennial => s.stats.prestigeCount >= PRESTIGE_PERENNIAL,
        .royal_treatment => s.availableJelly >= JELLY_ROYAL_TREATMENT,
        .full_crew => s.beeTypeCounts[0] > 0 and s.beeTypeCounts[1] > 0 and s.beeTypeCounts[2] > 0 and s.beeTypeCounts[3] > 0,
        .hive_mind => s.beesAlive >= BEES_HIVE_MIND,
        .swarm => s.beesAlive >= BEES_SWARM,
        .wholesale => s.largestPurchase >= BEES_WHOLESALE,
        .circle_of_life => s.stats.rottenCleared >= ROTTEN_CIRCLE_OF_LIFE,
        .well_read => s.allOneShotNodesOwned,
        .land_baron => s.gridRingLevel >= GRID_RING_LAND_BARON,
        .night_shift => s.nightShiftLevel >= NIGHT_SHIFT_MAX_LEVEL,
        .dont_poke_the_hive => s.hiveClickStreak >= HIVE_CLICKS_DONT_POKE,
        .sticky_situation => s.fullStorageSeconds >= FULL_STORAGE_SECONDS,
    };
}

/// Which achievements this profile has unlocked. Persisted in the save so
/// unlocks earned offline are known (and re-pushed to Steam on the next
/// connected launch).
pub const Tracker = struct {
    unlocked: [COUNT]bool = @splat(false),

    pub fn isUnlocked(self: *const Tracker, id: Id) bool {
        return self.unlocked[@intFromEnum(id)];
    }

    pub fn unlockedCount(self: *const Tracker) usize {
        var n: usize = 0;
        for (self.unlocked) |u| n += @intFromBool(u);
        return n;
    }

    /// Mark every satisfied, not-yet-unlocked achievement and return the
    /// newly unlocked ids (in display order) in `out`.
    pub fn evaluate(self: *Tracker, snapshot: *const Snapshot, out: *[COUNT]Id) []const Id {
        var n: usize = 0;
        for (&DEFS) |*d| {
            const i = @intFromEnum(d.id);
            if (self.unlocked[i]) continue;
            if (!isSatisfied(d.id, snapshot)) continue;
            self.unlocked[i] = true;
            out[n] = d.id;
            n += 1;
        }
        return out[0..n];
    }

    pub fn reset(self: *Tracker) void {
        self.unlocked = @splat(false);
    }
};

// ---- tests ----------------------------------------------------------------------

test "definitions are unique and consistent" {
    var seen = std.StringHashMap(void).init(std.testing.allocator);
    defer seen.deinit();
    for (&DEFS) |*d| {
        try std.testing.expect(!seen.contains(d.api));
        try seen.put(d.api, {});
        try std.testing.expect(d.name_en.len > 0 and d.name_pt.len > 0);
        try std.testing.expect(d.desc_en.len > 0 and d.desc_pt.len > 0);
        try std.testing.expectEqual(d.id, findByApi(d.api).?);
    }
    try std.testing.expectEqual(@as(?Id, null), findByApi("nope"));
    // Hidden ones sit at the end of the display order.
    var sawHidden = false;
    for (&DEFS) |*d| {
        if (d.hidden) sawHidden = true else try std.testing.expect(!sawHidden);
    }
}

test "a fresh profile satisfies nothing" {
    const snap = Snapshot{};
    for (&DEFS) |*d| try std.testing.expect(!isSatisfied(d.id, &snap));
}

test "honey milestones unlock in order from lifetime honey" {
    var t = Tracker{};
    var out: [COUNT]Id = undefined;
    var snap = Snapshot{};

    snap.stats.lifetimeHoney = 999;
    try std.testing.expectEqual(@as(usize, 0), t.evaluate(&snap, &out).len);

    snap.stats.lifetimeHoney = 1_000;
    const first = t.evaluate(&snap, &out);
    try std.testing.expectEqual(@as(usize, 1), first.len);
    try std.testing.expectEqual(Id.first_drop, first[0]);

    // Already unlocked ones never fire twice; a big jump fires all the rest.
    snap.stats.lifetimeHoney = 5e9;
    const rest = t.evaluate(&snap, &out);
    try std.testing.expectEqual(@as(usize, 3), rest.len);
    try std.testing.expectEqual(Id.local_business, rest[0]);
    try std.testing.expectEqual(Id.liquid_gold, rest[1]);
    try std.testing.expectEqual(Id.bee_llionaire, rest[2]);
    try std.testing.expectEqual(@as(usize, 0), t.evaluate(&snap, &out).len);
    try std.testing.expectEqual(@as(usize, 4), t.unlockedCount());
}

test "super flower rules" {
    var snap = Snapshot{};
    try std.testing.expect(!isSatisfied(.super_bloom, &snap));
    snap.stats.superFlowersMerged = 1;
    try std.testing.expect(isSatisfied(.super_bloom, &snap));

    snap.superFlowersAlive = 7;
    try std.testing.expect(!isSatisfied(.field_of_giants, &snap));
    snap.superFlowersAlive = 8;
    try std.testing.expect(isSatisfied(.field_of_giants, &snap));

    snap.superTypesAlive = .{ true, true, false };
    try std.testing.expect(!isSatisfied(.botanical_trifecta, &snap));
    snap.superTypesAlive = .{ true, true, true };
    try std.testing.expect(isSatisfied(.botanical_trifecta, &snap));
}

test "prestige rules" {
    var snap = Snapshot{};
    snap.stats.prestigeCount = 1;
    try std.testing.expect(isSatisfied(.long_live_the_queen, &snap));
    try std.testing.expect(!isSatisfied(.dynasty, &snap));
    snap.stats.prestigeCount = 5;
    try std.testing.expect(isSatisfied(.dynasty, &snap));
    try std.testing.expect(!isSatisfied(.perennial, &snap));
    snap.stats.prestigeCount = 10;
    try std.testing.expect(isSatisfied(.perennial, &snap));

    snap.availableJelly = 99;
    try std.testing.expect(!isSatisfied(.royal_treatment, &snap));
    snap.availableJelly = 100;
    try std.testing.expect(isSatisfied(.royal_treatment, &snap));
}

test "colony rules" {
    var snap = Snapshot{};
    snap.beeTypeCounts = .{ 5, 1, 1, 0 };
    try std.testing.expect(!isSatisfied(.full_crew, &snap));
    snap.beeTypeCounts = .{ 5, 1, 1, 1 };
    try std.testing.expect(isSatisfied(.full_crew, &snap));

    snap.beesAlive = 99;
    try std.testing.expect(!isSatisfied(.hive_mind, &snap));
    snap.beesAlive = 100;
    try std.testing.expect(isSatisfied(.hive_mind, &snap));
    try std.testing.expect(!isSatisfied(.swarm, &snap));
    snap.beesAlive = 1_000_000;
    try std.testing.expect(isSatisfied(.swarm, &snap));

    snap.largestPurchase = 99;
    try std.testing.expect(!isSatisfied(.wholesale, &snap));
    snap.largestPurchase = 100;
    try std.testing.expect(isSatisfied(.wholesale, &snap));

    snap.stats.rottenCleared = 50;
    try std.testing.expect(isSatisfied(.circle_of_life, &snap));
}

test "tree and easter-egg rules" {
    var snap = Snapshot{};
    snap.allOneShotNodesOwned = true;
    try std.testing.expect(isSatisfied(.well_read, &snap));
    snap.gridRingLevel = 9;
    try std.testing.expect(!isSatisfied(.land_baron, &snap));
    snap.gridRingLevel = 10;
    try std.testing.expect(isSatisfied(.land_baron, &snap));
    snap.nightShiftLevel = 4;
    try std.testing.expect(isSatisfied(.night_shift, &snap));
    snap.hiveClickStreak = 19;
    try std.testing.expect(!isSatisfied(.dont_poke_the_hive, &snap));
    snap.hiveClickStreak = 20;
    try std.testing.expect(isSatisfied(.dont_poke_the_hive, &snap));
    snap.fullStorageSeconds = 59.9;
    try std.testing.expect(!isSatisfied(.sticky_situation, &snap));
    snap.fullStorageSeconds = 60;
    try std.testing.expect(isSatisfied(.sticky_situation, &snap));
}

test "stats round-trip through the generic accessors" {
    var s = Stats{};
    s.set(.lifetime_honey, 1.5e12);
    s.set(.prestige_count, 7);
    s.set(.max_bees_alive, -3); // garbage clamps to 0
    s.set(.rotten_cleared, std.math.nan(f64));
    try std.testing.expectEqual(@as(f64, 1.5e12), s.get(.lifetime_honey));
    try std.testing.expectEqual(@as(u32, 7), s.prestigeCount);
    try std.testing.expectEqual(@as(u32, 0), s.maxBeesAlive);
    try std.testing.expectEqual(@as(u32, 0), s.rottenCleared);
    try std.testing.expectEqual(Stat.max_bees_alive, Stat.fromApi("max_bees_alive").?);
    try std.testing.expectEqual(@as(?Stat, null), Stat.fromApi("bogus"));
    try std.testing.expectEqual(Stat.Kind.float, Stat.lifetime_honey.kind());
    try std.testing.expectEqual(Stat.Kind.int, Stat.prestige_count.kind());
}

test "milestone progress targets match the rule thresholds" {
    try std.testing.expectEqual(HONEY_FIRST_DROP, def(.first_drop).progress.?.target);
    try std.testing.expectEqual(HONEY_BEE_LLIONAIRE, def(.bee_llionaire).progress.?.target);
    try std.testing.expectEqual(@as(f64, PRESTIGE_PERENNIAL), def(.perennial).progress.?.target);
    try std.testing.expectEqual(@as(f64, BEES_SWARM), def(.swarm).progress.?.target);
    try std.testing.expectEqual(@as(f64, ROTTEN_CIRCLE_OF_LIFE), def(.circle_of_life).progress.?.target);
}
